    const LOCK_RIGHT  = Math.max(16, CFG.RIGHT);   // 最小 16px，防止贴死屏幕边
    const LOCK_BOTTOM = Math.max(16, CFG.BOTTOM);  // 最小 16px，避让系统手势区
    // =========================================================

    let btn, rafId = 0, visible = false;
